const allItems = $input.all();
const parentData = $('Workflow Input').first().json;
const products = allItems.filter(i => i.json && i.json.stock !== undefined).map(item => item.json);
return [{
  json: {
    products_json: JSON.stringify(products),
    in_stock_count: products.length,
    has_products: products.length > 0,
    business_id: parentData.business_id,
    business_name: parentData.business_name,
    intent: parentData.intent,
    entities: parentData.entities,
    language: parentData.language,
    chatId: parentData.chatId,
    phoneNumber: parentData.phoneNumber,
    messageText: parentData.messageText || 'What products do you have?',
    chatInput: parentData.messageText || 'What products do you have?',
    discount_json: 'null',
    pricing_json: 'null'
  }
}];

const parentData = $('Workflow Input').first().json;
return [{
  json: {
    products_json: JSON.stringify([]),
    in_stock_count: 0,
    has_products: false,
    business_id: parentData.business_id,
    business_name: parentData.business_name,
    intent: parentData.intent,
    entities: parentData.entities,
    language: parentData.language,
    chatId: parentData.chatId,
    phoneNumber: parentData.phoneNumber,
    messageText: parentData.messageText || '',
    discount_json: 'null',
    pricing_json: 'null'
  }
}];

const ctx = $('Workflow Input').first().json;
const replyText = $input.item.json.text ?? $input.item.json.output ?? $input.item.json.response ?? '';
// Also try to safely get products
let hasImage = false;
let imageUrl = null;
try {
    const products = JSON.parse($('Prepare AI Input').first()?.json?.products_json ?? '[]');
    if (products.length > 0 && products[0].image_url) {
        hasImage = true;
        imageUrl = products[0].image_url;
    }
} catch(e) {}

return [{
  json: {
    replyText: replyText,
    chatId: ctx.chatId,
    business_id: ctx.business_id,
    phoneNumber: ctx.phoneNumber,
    hasImage: hasImage,
    imageUrl: imageUrl
  }
}];
